from torch.utils.cpp_extension import load_inline

conv3d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#define TILE_H 16
#define TILE_W 16
#define OC_TILE 8
#define TILE_D 4
__global__ void conv3d_forward_kernel_tiled(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int D_out, int H_out, int W_out,
    int kD, int kH, int kW,
    int stride, int padding, int dilation,
    int groups, int C_in_per_group, int C_out_per_group,
    int SH, int SW, int numOcTiles, int numDTiles,
    bool has_bias)
{
    extern __shared__ float smem[];
    float* s_input = smem;                              // C_in_per_group * SH * SW * TILE_D
    float* s_weight = smem + C_in_per_group * SH * SW * TILE_D;   // OC_TILE * C_in_per_group * kH * kW
    float* s_output = s_weight + OC_TILE * C_in_per_group * kH * kW; // TILE_H * TILE_W * TILE_D staging buffer for coalesced writes
    int w_out0 = blockIdx.x * TILE_W;
    int h_out0 = blockIdx.y * TILE_H;
    int w_out = w_out0 + threadIdx.x;
    int h_out = h_out0 + threadIdx.y;
    int z = blockIdx.z;
    int oc_tile_idx = z % numOcTiles; z /= numOcTiles;
    int group_id = z % groups; z /= groups;
    int d_tile = z % numDTiles; z /= numDTiles;
    int n = z;
    int ic_start = group_id * C_in_per_group;
    int oc_start = group_id * C_out_per_group + oc_tile_idx * OC_TILE;
    int oc_count = OC_TILE;
    if (oc_tile_idx * OC_TILE + OC_TILE > C_out_per_group) {
        oc_count = C_out_per_group - oc_tile_idx * OC_TILE;
    }
    float acc[TILE_D][OC_TILE];
    #pragma unroll
    for (int dt = 0; dt < TILE_D; ++dt) {
        #pragma unroll
        for (int i = 0; i < OC_TILE; ++i) acc[dt][i] = 0.0f;
    }
    int tid = threadIdx.y * TILE_W + threadIdx.x;
    int block_threads = TILE_W * TILE_H;
    int sinput_plane = SH * SW;
    int total_load_in = C_in_per_group * sinput_plane * TILE_D;
    int total_load_w = oc_count * C_in_per_group * kH * kW;
    int d_out_base = d_tile * TILE_D;
    for (int kd = 0; kd < kD; ++kd) {
        int d_in0 = d_out_base * stride - padding + kd * dilation;
        for (int idx = tid; idx < total_load_in; idx += block_threads) {
            int dt = idx % TILE_D;
            int idx2 = idx / TILE_D;
            int sw = idx2 % SW;
            int idx3 = idx2 / SW;
            int sh = idx3 % SH;
            int ic = idx3 / SH;
            int h_in = h_out0 * stride - padding + sh;
            int w_in = w_out0 * stride - padding + sw;
            int d_in = d_in0 + dt * stride;
            float val = 0.0f;
            if (h_in >= 0 && h_in < H_in && w_in >= 0 && w_in < W_in && d_in >= 0 && d_in < D_in) {
                int in_c = ic_start + ic;
                long off = (((long)n * C_in + in_c) * H_in + h_in) * W_in + w_in;
                off = off * D_in + d_in;
                val = input[off];
            }
            s_input[idx] = val;
        }
        for (int idx = tid; idx < total_load_w; idx += block_threads) {
            int oc_local = idx / (C_in_per_group * kH * kW);
            int rem = idx % (C_in_per_group * kH * kW);
            int ic = rem / (kH * kW);
            int rem2 = rem % (kH * kW);
            int kh = rem2 / kW;
            int kw = rem2 % kW;
            int oc = oc_start + oc_local;
            long w_off = ((long)oc * C_in_per_group + ic) * kD * kH * kW + (kd * kH + kh) * kW + kw;
            s_weight[idx] = weight[w_off];
        }
        __syncthreads();
        if (h_out < H_out && w_out < W_out) {
            int local_h = threadIdx.y * stride;
            int local_w = threadIdx.x * stride;
            for (int ic = 0; ic < C_in_per_group; ++ic) {
                for (int kh = 0; kh < kH; ++kh) {
                    int sh = local_h + kh * dilation;
                    for (int kw = 0; kw < kW; ++kw) {
                        int sw = local_w + kw * dilation;
                        int base_idx = ((ic * SH + sh) * SW + sw) * TILE_D;
                        const float4 in_val4 = *reinterpret_cast<const float4*>(s_input + base_idx);
                        const float* w_base = s_weight + (ic * kH + kh) * kW + kw;
                        #pragma unroll
                        for (int oc_local = 0; oc_local < OC_TILE; ++oc_local) {
                            if (oc_local < oc_count) {
                                float w_val = w_base[oc_local * C_in_per_group * kH * kW];
                                acc[0][oc_local] += in_val4.x * w_val;
                                acc[1][oc_local] += in_val4.y * w_val;
                                acc[2][oc_local] += in_val4.z * w_val;
                                acc[3][oc_local] += in_val4.w * w_val;
                            }
                        }
                    }
                }
            }
        }
        __syncthreads();
    }
    {
        int total_out_elems = TILE_H * TILE_W * TILE_D;
        int local_base = (threadIdx.y * TILE_W + threadIdx.x) * TILE_D;
        bool valid_thread = (h_out < H_out && w_out < W_out);
        for (int oc_local = 0; oc_local < oc_count; ++oc_local) {
            int oc = oc_start + oc_local;
            if (valid_thread) {
                #pragma unroll
                for (int dt = 0; dt < TILE_D; ++dt) {
                    float val = acc[dt][oc_local];
                    if (has_bias) val += bias[oc];
                    s_output[local_base + dt] = val;
                }
            }
            __syncthreads();
            for (int idx = tid; idx < total_out_elems; idx += block_threads) {
                int dt = idx % TILE_D;
                int idx2 = idx / TILE_D;
                int w_local = idx2 % TILE_W;
                int h_local = idx2 / TILE_W;
                int h_o = h_out0 + h_local;
                int w_o = w_out0 + w_local;
                int d_o = d_out_base + dt;
                if (h_o < H_out && w_o < W_out && d_o < D_out) {
                    long out_idx = ((((long)n * C_out + oc) * H_out + h_o) * W_out + w_o) * D_out + d_o;
                    output[out_idx] = s_output[idx];
                }
            }
            __syncthreads();
        }
    }
}
torch::Tensor conv3d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    int groups,
    bool has_bias)
{
    input = input.contiguous();
    weight = weight.contiguous();
    int N = input.size(0);
    int C_in = input.size(1);
    int H_in = input.size(2);
    int W_in = input.size(3);
    int D_in = input.size(4);
    int C_out = weight.size(0);
    int C_in_per_group = weight.size(1);
    int kH = weight.size(2);
    int kW = weight.size(3);
    int kD = weight.size(4);
    int C_out_per_group = C_out / groups;
    int H_out = (H_in + 2 * padding - dilation * (kH - 1) - 1) / stride + 1;
    int W_out = (W_in + 2 * padding - dilation * (kW - 1) - 1) / stride + 1;
    int D_out = (D_in + 2 * padding - dilation * (kD - 1) - 1) / stride + 1;
    auto output = torch::zeros({N, C_out, H_out, W_out, D_out}, input.options());
    int SH = (TILE_H - 1) * stride + (kH - 1) * dilation + 1;
    int SW = (TILE_W - 1) * stride + (kW - 1) * dilation + 1;
    int numOcTiles = (C_out_per_group + OC_TILE - 1) / OC_TILE;
    int numDTiles = (D_out + TILE_D - 1) / TILE_D;
    dim3 block(TILE_W, TILE_H);
    dim3 grid(
        (W_out + TILE_W - 1) / TILE_W,
        (H_out + TILE_H - 1) / TILE_H,
        (unsigned int)((long)N * numDTiles * groups * numOcTiles)
    );
    size_t shared_bytes = (size_t)(C_in_per_group * SH * SW * TILE_D + OC_TILE * C_in_per_group * kH * kW + TILE_H * TILE_W * TILE_D) * sizeof(float);
    const float* bias_ptr = has_bias ? bias.contiguous().data_ptr<float>() : nullptr;
    conv3d_forward_kernel_tiled<<<grid, block, shared_bytes>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, C_in, D_in, H_in, W_in,
        C_out, D_out, H_out, W_out,
        kD, kH, kW,
        stride, padding, dilation,
        groups, C_in_per_group, C_out_per_group,
        SH, SW, numOcTiles, numDTiles,
        has_bias
    );
    return output;
}
